import React from 'react';
import {
  AbsoluteFill,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
  spring,
} from 'remotion';

// PAI Theme
const T = {
  bg: '#0f172a',
  bgAlt: '#1e293b',
  bgDark: '#020617',
  accent: '#8b5cf6',
  accentLight: '#a78bfa',
  accentMuted: '#6366f1',
  text: '#f1f5f9',
  textMuted: '#94a3b8',
  textDark: '#64748b',
  success: '#10b981',
  warning: '#f59e0b',
};

// Eased fade helper
function fadeIn(frame: number, start: number, duration: number) {
  return interpolate(frame, [start, start + duration], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.out(Easing.ease),
  });
}

function fadeOut(frame: number, start: number, duration: number) {
  return interpolate(frame, [start, start + duration], [1, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.in(Easing.ease),
  });
}

function slideUp(frame: number, start: number, duration: number, dist = 40) {
  const p = interpolate(frame, [start, start + duration], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.out(Easing.cubic),
  });
  return `translateY(${dist * (1 - p)}px)`;
}

// ── Scene 1: Title ──────────────────────────────────────────────────────────
function SceneTitle() {
  const frame = useCurrentFrame();
  const opacity = fadeIn(frame, 0, 20);
  const tagOpacity = fadeIn(frame, 18, 15);
  const lineScale = interpolate(frame, [15, 40], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.out(Easing.back(1.5)),
  });

  return (
    <AbsoluteFill style={{ background: T.bg, justifyContent: 'center', alignItems: 'center', flexDirection: 'column' }}>
      {/* Background glow */}
      <div style={{
        position: 'absolute', width: 600, height: 600,
        background: `radial-gradient(circle, ${T.accent}22 0%, transparent 70%)`,
        borderRadius: '50%',
      }} />

      <div style={{ opacity, transform: slideUp(frame, 0, 25) }}>
        <div style={{ fontSize: 72, fontWeight: 800, color: T.text, letterSpacing: -2, textAlign: 'center', fontFamily: 'system-ui, sans-serif', lineHeight: 1.1 }}>
          Agent Register
        </div>
        {/* Accent line */}
        <div style={{
          height: 4, background: `linear-gradient(90deg, ${T.accent}, ${T.accentMuted})`,
          borderRadius: 2, marginTop: 16,
          transform: `scaleX(${lineScale})`, transformOrigin: 'left',
        }} />
      </div>

      <div style={{ opacity: tagOpacity, marginTop: 24, transform: slideUp(frame, 18, 20) }}>
        <div style={{ fontSize: 24, color: T.textMuted, textAlign: 'center', fontFamily: 'system-ui, sans-serif', letterSpacing: 1 }}>
          One view. Every agent. Governed.
        </div>
      </div>
    </AbsoluteFill>
  );
}

// ── Scene 2: The Problem ────────────────────────────────────────────────────
function SceneProblem() {
  const frame = useCurrentFrame();

  const lines = [
    { text: 'Agents shipping without governance', icon: '⚠️' },
    { text: 'No single source of truth', icon: '🔀' },
    { text: 'Lifecycle state invisible to stakeholders', icon: '🔍' },
  ];

  return (
    <AbsoluteFill style={{ background: T.bgDark, padding: 80, flexDirection: 'column', justifyContent: 'center' }}>
      <div style={{ opacity: fadeIn(frame, 0, 15), transform: slideUp(frame, 0, 20) }}>
        <div style={{ fontSize: 16, color: T.accent, letterSpacing: 3, textTransform: 'uppercase', fontFamily: 'system-ui, sans-serif', marginBottom: 16 }}>
          The Problem
        </div>
        <div style={{ fontSize: 52, fontWeight: 700, color: T.text, fontFamily: 'system-ui, sans-serif', lineHeight: 1.15, marginBottom: 48 }}>
          AI agent delivery<br />without visibility
        </div>
      </div>

      {lines.map((line, i) => {
        const delay = 20 + i * 12;
        return (
          <div key={i} style={{
            opacity: fadeIn(frame, delay, 12),
            transform: slideUp(frame, delay, 15),
            display: 'flex', alignItems: 'center', gap: 20,
            background: T.bgAlt, borderRadius: 12, padding: '18px 24px',
            marginBottom: 16, borderLeft: `3px solid ${T.warning}`,
          }}>
            <span style={{ fontSize: 28 }}>{line.icon}</span>
            <span style={{ fontSize: 22, color: T.textMuted, fontFamily: 'system-ui, sans-serif' }}>{line.text}</span>
          </div>
        );
      })}
    </AbsoluteFill>
  );
}

// ── Scene 3: The Solution ───────────────────────────────────────────────────
function SceneSolution() {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const pillars = [
    { label: 'Power App', desc: 'Register & lifecycle UI', color: T.accent },
    { label: 'SharePoint Lists', desc: 'Governed data store', color: T.accentMuted },
    { label: 'Azure DevOps', desc: 'Delivery execution sync', color: T.success },
    { label: 'Power Automate', desc: 'Automated mesh sync', color: T.warning },
  ];

  return (
    <AbsoluteFill style={{ background: T.bg, padding: 80, flexDirection: 'column', justifyContent: 'center' }}>
      <div style={{ opacity: fadeIn(frame, 0, 15), transform: slideUp(frame, 0, 18) }}>
        <div style={{ fontSize: 16, color: T.accent, letterSpacing: 3, textTransform: 'uppercase', fontFamily: 'system-ui, sans-serif', marginBottom: 16 }}>
          The Solution
        </div>
        <div style={{ fontSize: 48, fontWeight: 700, color: T.text, fontFamily: 'system-ui, sans-serif', lineHeight: 1.15, marginBottom: 12 }}>
          Four layers. One mesh.
        </div>
        <div style={{ fontSize: 22, color: T.textMuted, fontFamily: 'system-ui, sans-serif', marginBottom: 48 }}>
          Power App controls movement. ADO executes work.<br />
          SharePoint stores evidence. Power Automate keeps it live.
        </div>
      </div>

      <div style={{ display: 'flex', gap: 20 }}>
        {pillars.map((p, i) => {
          const delay = 18 + i * 10;
          return (
            <div key={i} style={{
              opacity: fadeIn(frame, delay, 12),
              transform: slideUp(frame, delay, 14),
              flex: 1,
              background: T.bgAlt,
              borderRadius: 16,
              padding: '28px 24px',
              borderTop: `3px solid ${p.color}`,
            }}>
              <div style={{ fontSize: 20, fontWeight: 700, color: p.color, fontFamily: 'system-ui, sans-serif', marginBottom: 8 }}>
                {p.label}
              </div>
              <div style={{ fontSize: 16, color: T.textMuted, fontFamily: 'system-ui, sans-serif' }}>
                {p.desc}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
}

// ── Scene 4: Lifecycle Gates ────────────────────────────────────────────────
function SceneLifecycle() {
  const frame = useCurrentFrame();

  const stages = ['Idea', 'Discovery', 'Build', 'Review', 'Staging', 'Live'];
  const activeIdx = Math.floor(interpolate(frame, [10, 55], [0, 5], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  }));

  return (
    <AbsoluteFill style={{ background: T.bgDark, padding: 80, flexDirection: 'column', justifyContent: 'center' }}>
      <div style={{ opacity: fadeIn(frame, 0, 15), transform: slideUp(frame, 0, 18) }}>
        <div style={{ fontSize: 16, color: T.accent, letterSpacing: 3, textTransform: 'uppercase', fontFamily: 'system-ui, sans-serif', marginBottom: 16 }}>
          Governed Lifecycle
        </div>
        <div style={{ fontSize: 48, fontWeight: 700, color: T.text, fontFamily: 'system-ui, sans-serif', lineHeight: 1.15, marginBottom: 16 }}>
          No register update,<br />no stage movement.
        </div>
        <div style={{ fontSize: 20, color: T.textMuted, fontFamily: 'system-ui, sans-serif', marginBottom: 48 }}>
          Gate reviews enforce readiness before every promotion.
        </div>
      </div>

      {/* Pipeline */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 0 }}>
        {stages.map((s, i) => {
          const isActive = i <= activeIdx;
          const isCurrent = i === activeIdx;
          return (
            <React.Fragment key={i}>
              <div style={{
                opacity: fadeIn(frame, 8 + i * 8, 10),
                background: isActive ? (isCurrent ? T.accent : T.accentMuted) : T.bgAlt,
                borderRadius: 10,
                padding: '14px 20px',
                textAlign: 'center',
                minWidth: 100,
                border: isCurrent ? `2px solid ${T.accentLight}` : '2px solid transparent',
                transform: isCurrent ? 'scale(1.08)' : 'scale(1)',
              }}>
                <div style={{ fontSize: 15, fontWeight: isCurrent ? 700 : 500, color: isActive ? T.text : T.textDark, fontFamily: 'system-ui, sans-serif' }}>
                  {s}
                </div>
              </div>
              {i < stages.length - 1 && (
                <div style={{
                  opacity: fadeIn(frame, 10 + i * 8, 8),
                  flex: 1, height: 2,
                  background: i < activeIdx ? T.accentMuted : T.bgAlt,
                }} />
              )}
            </React.Fragment>
          );
        })}
      </div>
    </AbsoluteFill>
  );
}

// ── Scene 5: Key Features ───────────────────────────────────────────────────
function SceneFeatures() {
  const frame = useCurrentFrame();

  const features = [
    { icon: '🗂️', title: 'Agent Dossier', desc: 'Full template workspace per agent — scope, owner, risks, dependencies' },
    { icon: '✅', title: 'DoR / DoD Gates', desc: 'Readiness checklists enforced before stage promotion' },
    { icon: '🔗', title: 'ADO Sync', desc: 'Live delivery data pulled from Azure DevOps — no manual copy' },
    { icon: '📊', title: 'Portfolio View', desc: 'Governance dashboard across all agents — exceptions surface automatically' },
  ];

  return (
    <AbsoluteFill style={{ background: T.bg, padding: 80, flexDirection: 'column', justifyContent: 'center' }}>
      <div style={{ opacity: fadeIn(frame, 0, 15), marginBottom: 40 }}>
        <div style={{ fontSize: 16, color: T.accent, letterSpacing: 3, textTransform: 'uppercase', fontFamily: 'system-ui, sans-serif', marginBottom: 12 }}>
          What It Does
        </div>
        <div style={{ fontSize: 48, fontWeight: 700, color: T.text, fontFamily: 'system-ui, sans-serif' }}>
          Key capabilities
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
        {features.map((f, i) => {
          const delay = 15 + i * 10;
          return (
            <div key={i} style={{
              opacity: fadeIn(frame, delay, 12),
              transform: slideUp(frame, delay, 14),
              background: T.bgAlt,
              borderRadius: 16,
              padding: '24px 28px',
              display: 'flex',
              gap: 20,
              alignItems: 'flex-start',
            }}>
              <span style={{ fontSize: 36, lineHeight: 1 }}>{f.icon}</span>
              <div>
                <div style={{ fontSize: 20, fontWeight: 700, color: T.text, fontFamily: 'system-ui, sans-serif', marginBottom: 6 }}>
                  {f.title}
                </div>
                <div style={{ fontSize: 16, color: T.textMuted, fontFamily: 'system-ui, sans-serif', lineHeight: 1.5 }}>
                  {f.desc}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
}

// ── Scene 6: Close ──────────────────────────────────────────────────────────
function SceneClose() {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const pulse = interpolate(
    Math.sin((frame / fps) * Math.PI * 2),
    [-1, 1], [0.95, 1.05]
  );

  return (
    <AbsoluteFill style={{ background: T.bgDark, justifyContent: 'center', alignItems: 'center', flexDirection: 'column' }}>
      <div style={{
        position: 'absolute', width: 500, height: 500,
        background: `radial-gradient(circle, ${T.accent}30 0%, transparent 70%)`,
        borderRadius: '50%',
        transform: `scale(${pulse})`,
      }} />

      <div style={{ opacity: fadeIn(frame, 0, 20), textAlign: 'center' }}>
        <div style={{ fontSize: 64, fontWeight: 800, color: T.text, fontFamily: 'system-ui, sans-serif', letterSpacing: -1, marginBottom: 20 }}>
          Agent Register
        </div>
        <div style={{ width: 120, height: 4, background: `linear-gradient(90deg, ${T.accent}, ${T.accentMuted})`, borderRadius: 2, margin: '0 auto 28px' }} />
      </div>

      <div style={{ opacity: fadeIn(frame, 20, 15), textAlign: 'center' }}>
        <div style={{ fontSize: 26, color: T.textMuted, fontFamily: 'system-ui, sans-serif', lineHeight: 1.6 }}>
          Built on Power Platform · Governed by design<br />
          <span style={{ color: T.accent }}>Deliver AI with confidence.</span>
        </div>
      </div>
    </AbsoluteFill>
  );
}

// ── Root composition ─────────────────────────────────────────────────────────
export const AgentRegisterVideo: React.FC = () => {
  return (
    <AbsoluteFill style={{ background: T.bg }}>
      <Sequence from={0}   durationInFrames={75}><SceneTitle /></Sequence>
      <Sequence from={70}  durationInFrames={75}><SceneProblem /></Sequence>
      <Sequence from={140} durationInFrames={80}><SceneSolution /></Sequence>
      <Sequence from={215} durationInFrames={80}><SceneLifecycle /></Sequence>
      <Sequence from={290} durationInFrames={80}><SceneFeatures /></Sequence>
      <Sequence from={365} durationInFrames={75}><SceneClose /></Sequence>
    </AbsoluteFill>
  );
};

